// ─────────────────────────────────────────────────────────────────
// TYPE DEFINITIONS
// ─────────────────────────────────────────────────────────────────

/**
 * HttpMethod
 * -----------
 * The set of HTTP methods supported by the API builder.
 * These map directly to REST conventions:
 *  - GET    → read/list data
 *  - POST   → create new data
 *  - PUT    → replace existing data
 *  - DELETE → remove data
 *  - PATCH  → partially update data
 */
type HttpMethod = 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH'

/**
 * EndpointType
 * -------------
 * Whether an endpoint was auto-generated by Underpeaks from a model ('auto')
 * or manually created by a developer with custom business logic ('custom').
 */
type EndpointType = 'auto' | 'custom'

/**
 * Endpoint
 * ---------
 * Represents a single API endpoint shown in the Endpoints tab.
 *
 * @prop id          - Unique identifier for the endpoint
 * @prop method      - HTTP method (GET, POST, etc.)
 * @prop path        - The URL path (e.g. '/api/data/products/:id')
 * @prop description - A human-readable description of what the endpoint does
 * @prop type        - Whether this is auto-generated or a custom endpoint
 * @prop model       - The CMS model this endpoint belongs to (auto endpoints only)
 * @prop auth        - Whether this endpoint requires an API key / Bearer token
 */
type Endpoint = {
  id:          string
  method:      HttpMethod
  path:        string
  description: string
  type:        EndpointType
  model?:      string
  auth:        boolean
}

/**
 * ApiKey
 * -------
 * Represents a single API key entry shown in the API Keys tab.
 *
 * @prop id       - Unique identifier for the key
 * @prop name     - A human-readable label for the key (e.g. 'Production Key')
 * @prop key      - The actual API key string. In production this should only
 *                  be fetched from the server when the user explicitly reveals it.
 * @prop created  - Human-readable creation date string
 * @prop lastUsed - Human-readable last-used date string, or 'Never'
 * @prop active   - Whether the key is currently active and usable
 */
type ApiKey = {
  id:       string
  name:     string
  key:      string
  created:  string
  lastUsed: string
  active:   boolean
}

