// STYLE CONSTANTS
// ─────────────────────────────────────────────────────────────────

/**
 * methodColors
 * -------------
 * Maps each HTTP method to a set of Tailwind CSS classes for the method badge.
 * Each method has a distinct colour so they can be identified at a glance.
 */
const methodColors: Record<HttpMethod, string> = {
  GET:    'bg-green-50 text-green-700 border-green-200',
  POST:   'bg-blue-50 text-blue-700 border-blue-200',
  PUT:    'bg-amber-50 text-amber-700 border-amber-200',
  DELETE: 'bg-red-50 text-red-700 border-red-200',
  PATCH:  'bg-purple-50 text-purple-700 border-purple-200',
}

// ─────────────────────────────────────────────────────────────────
// SUB-COMPONENTS
// ─────────────────────────────────────────────────────────────────

/**
 * MethodBadge
 * ------------
 * A small coloured pill that displays an HTTP method (GET, POST, etc.).
 * The colour is determined by the methodColors map above.
 *
 * @param method - The HTTP method to display
 */
function MethodBadge({ method }: { method: HttpMethod }) {
  return (
    <span
      className={`inline-block px-2 py-0.5 text-[10px] font-bold rounded border w-14 text-center shrink-0 ${methodColors[method]}`}
      aria-label={method}
    >
      {method}
    </span>
  )
}

/**
 * CopyButton
 * -----------
 * A small icon button that copies a given text string to the clipboard.
 * Shows a green checkmark for 2 seconds after copying to confirm the action.
 *
 * @param text - The string to copy to the clipboard when clicked
 */
function CopyButton({ text }: { text: string }) {
  const [copied, setCopied] = useState(false)
  const t = useTranslations('apiPage')

  return (
    <button
      onClick={() => {
        navigator.clipboard.writeText(text)
        setCopied(true)
        setTimeout(() => setCopied(false), 2000)
      }}
      className="p-1 rounded hover:bg-gray-100 text-gray-400 hover:text-gray-700 transition shrink-0"
      aria-label={copied ? t('copied') : t('copy')}
      title={copied ? t('copied') : t('copy')}
    >
      {copied
        ? <FiCheck size={13} className="text-green-500" aria-hidden="true" />
        : <FiCopy size={13} aria-hidden="true" />
      }
    </button>
  )
}

/**
 * EndpointRow
 * ------------
 * Renders a single endpoint as a collapsible row in the endpoints list.
 *
 * Collapsed state (default):
 *  Shows the method badge, path, description, model badge, auth icon,
 *  a copy button for the example URL, and a "Test" button on hover.
 *
 * Expanded state (when clicked):
 *  Shows an example request URL in a dark code block, the required
 *  Authorization header (if auth is required), and optionally a test panel
 *  where the user can send a mock request and see a mock response.
 *
 * @param endpoint - The endpoint data to display
 */
function EndpointRow({ endpoint }: { endpoint: Endpoint }) {
  // Controls whether the detail panel is shown below the row
  const [expanded, setExpanded] = useState(false)

  // Controls whether the test panel is shown within the expanded detail panel
  const [testOpen, setTestOpen] = useState(false)

  // The mock response JSON string shown in the test panel after running a test
  const [response, setResponse] = useState('')

  // Whether a test request is currently "in flight" (shows loading state on button)
  const [loading, setLoading] = useState(false)

  const t = useTranslations('apiPage')

  // Build the example URL shown in the expanded panel
  // GET endpoints include common query params as a usage hint
  const exampleUrl = `https://yourapp.com${endpoint.path}${
    endpoint.method === 'GET' ? '?limit=20&offset=0' : ''
  }`

  /**
   * runTest
   * --------
   * Simulates sending a request to this endpoint and shows a mock response.
   *
   * TODO: Replace this mock implementation with a real API call to the endpoint.
   * In production, this should actually call the endpoint (with the user's API key)
   * and display the real response — not a hardcoded mock.
   * The 800ms timeout simulates network latency for now.
   */
  const runTest = () => {
    setLoading(true)
    setTimeout(() => {
      setResponse(JSON.stringify({
        data: endpoint.method === 'GET'
          ? [{ id: '1', name: 'Example Item', status: 'active', created_at: new Date().toISOString() }]
          : { success: true, id: Date.now().toString() },
        total:   endpoint.method === 'GET' ? 1     : undefined,
        limit:   endpoint.method === 'GET' ? 20    : undefined,
        offset:  endpoint.method === 'GET' ? 0     : undefined,
        hasMore: endpoint.method === 'GET' ? false : undefined,
      }, null, 2))
      setLoading(false)
    }, 800)
  }

  return (
    <div className="border-b border-gray-100 last:border-0">

      {/* ── Collapsed row — always visible ── */}
      <div
        className="flex items-center gap-3 px-5 py-3 hover:bg-gray-50 cursor-pointer transition-colors group"
        onClick={() => setExpanded((v) => !v)}
        role="button"
        aria-expanded={expanded}
        tabIndex={0}
        onKeyDown={(e) => e.key === 'Enter' && setExpanded((v) => !v)}
      >
        <MethodBadge method={endpoint.method} />
        <p className="text-sm font-mono text-gray-800 flex-1 truncate">{endpoint.path}</p>
        <p className="text-xs text-gray-400 hidden md:block flex-1 truncate">{endpoint.description}</p>

        <div className="flex items-center gap-2 shrink-0">
          {/* Model badge — shows which CMS model this endpoint belongs to */}
          {endpoint.model && (
            <span className="text-[10px] bg-blue-50 text-blue-600 border border-blue-100 px-2 py-0.5 rounded-full font-medium hidden sm:block">
              {endpoint.model}
            </span>
          )}

          {/* Custom endpoint badge */}
          {endpoint.type === 'custom' && (
            <span className="text-[10px] bg-violet-50 text-violet-600 border border-violet-100 px-2 py-0.5 rounded-full font-medium hidden sm:block">
              {t('endpoints.customBadge')}
            </span>
          )}

          {/* Auth indicator — lock icon if auth required, unlock if public */}
          {endpoint.auth
            ? <FiLock size={12} className="text-amber-500" title={t('endpoints.requiresAuth')} aria-label={t('endpoints.requiresAuth')} />
            : <FiUnlock size={12} className="text-gray-300" title={t('endpoints.public')} aria-label={t('endpoints.public')} />
          }

          <CopyButton text={exampleUrl} />

          {/* Test button — only visible on row hover */}
          <button
            onClick={(e) => { e.stopPropagation(); setTestOpen((v) => !v) }}
            className="flex items-center gap-1 px-2 py-1 text-[10px] font-medium bg-gray-100 hover:bg-gray-800 hover:text-white text-gray-600 rounded transition opacity-0 group-hover:opacity-100"
            aria-label={t('endpoints.testButton')}
          >
            <FiPlay size={10} aria-hidden="true" />
            {t('endpoints.testButton')}
          </button>

          {/* Expand/collapse chevron */}
          {expanded
            ? <FiChevronUp size={14} className="text-gray-400" aria-hidden="true" />
            : <FiChevronDown size={14} className="text-gray-400" aria-hidden="true" />
          }
        </div>
      </div>

      {/* ── Expanded panel — shown when row is clicked ── */}
      {expanded && (
        <div className="px-5 pb-4 bg-gray-50 border-t border-gray-100">
          <div className="mt-3 flex flex-col gap-3">

            {/* Example request URL in a dark code block */}
            <div>
              <p className="text-[10px] font-semibold text-gray-400 uppercase mb-1">
                {t('endpoints.exampleRequest')}
              </p>
              <div className="flex items-center gap-2 px-3 py-2 bg-gray-900 rounded-md">
                <span className={`text-[10px] font-bold ${
                  endpoint.method === 'GET'    ? 'text-green-400' :
                  endpoint.method === 'POST'   ? 'text-blue-400'  :
                  endpoint.method === 'DELETE' ? 'text-red-400'   : 'text-amber-400'
                }`}>
                  {endpoint.method}
                </span>
                <p className="text-xs text-gray-300 font-mono flex-1 truncate">{exampleUrl}</p>
                <CopyButton text={exampleUrl} />
              </div>
            </div>

            {/* Required auth header — only shown if this endpoint requires auth */}
            {endpoint.auth && (
              <div>
                <p className="text-[10px] font-semibold text-gray-400 uppercase mb-1">
                  {t('endpoints.requiredHeaders')}
                </p>
                <div className="px-3 py-2 bg-gray-900 rounded-md">
                  <p className="text-xs font-mono text-gray-300">
                    Authorization: Bearer <span className="text-amber-400">{'<your-api-key>'}</span>
                  </p>
                </div>
              </div>
            )}

            {/* Test panel — shown when the Test button is clicked */}
            {testOpen && (
              <div>
                <p className="text-[10px] font-semibold text-gray-400 uppercase mb-1">
                  {t('endpoints.testLabel')}
                </p>
                <div className="flex flex-col gap-2">
                  <button
                    onClick={runTest}
                    disabled={loading}
                    className="flex items-center gap-1.5 px-3 py-2 bg-gray-900 text-white text-xs font-medium rounded-md hover:bg-gray-700 disabled:opacity-50 transition w-fit"
                  >
                    <FiPlay size={11} aria-hidden="true" />
                    {loading ? t('endpoints.running') : t('endpoints.sendRequest')}
                  </button>

                  {/* Mock response output */}
                  {response && (
                    <pre className="text-[11px] bg-gray-900 text-green-400 font-mono p-3 rounded-md overflow-x-auto">
                      {response}
                    </pre>
                  )}
                </div>
              </div>
            )}

          </div>
        </div>
      )}
    </div>
  )
}

/**
 * CustomEndpointDrawer
 * ----------------------
 * A slide-in panel from the right side of the screen for creating a new custom endpoint.
 *
 * What is a custom endpoint?
 * ---------------------------
 * Unlike auto-generated endpoints (which Underpeaks creates from your models),
 * custom endpoints contain your own business logic. For example, you might create
 * a POST /api/custom/checkout endpoint that creates an order, sends a confirmation
 * email, and decrements stock — all in one API call.
 *
 * The drawer lets you configure:
 *  - HTTP method (GET, POST, PUT, DELETE, PATCH)
 *  - URL path (must start with /api/custom/)
 *  - Description
 *  - Authentication requirement (required or public)
 *  - Handler code (a JavaScript function template to fill in)
 *
 * @param open     - Whether the drawer is currently visible
 * @param onClose  - Callback to close the drawer (called by cancel button and backdrop click)
 * @param onCreate - Callback called with the new Endpoint object when the user clicks Create
 */
function CustomEndpointDrawer({ open, onClose, onCreate }: {
  open:     boolean
  onClose:  () => void
  onCreate: (e: Endpoint) => void
}) {
  const [method,      setMethod]      = useState<HttpMethod>('POST')
  const [path,        setPath]        = useState('/api/custom/')
  const [description, setDescription] = useState('')
  const [auth,        setAuth]        = useState(true)
  const [code,        setCode]        = useState(
`// Custom endpoint handler
// Call your generic API, add business logic, integrate services

export async function handler(req, res) {
  const { productId, quantity } = req.body;
  const product = await fetch(\`/api/data/products/\${productId}\`);
  // Your business logic here
  return res.json({ success: true });
}`
  )

  const t = useTranslations('apiPage')

  // Don't render anything if the drawer is closed — avoids keeping it in the DOM
  if (!open) return null

  return (
    <>
      {/* Semi-transparent backdrop — clicking it closes the drawer */}
      <div
        className="fixed inset-0 bg-black/20 z-40"
        onClick={onClose}
        aria-hidden="true"
      />

      {/* Drawer panel */}
      <div
        className="fixed top-16 right-0 bottom-0 w-full max-w-lg bg-white border-l border-gray-200 z-50 flex flex-col shadow-2xl"
        role="dialog"
        aria-modal="true"
        aria-label={t('drawer.title')}
      >

        {/* Drawer header */}
        <div className="flex items-center justify-between px-5 py-4 border-b border-gray-100 shrink-0">
          <div>
            <h2 className="text-sm font-bold text-gray-900">{t('drawer.title')}</h2>
            <p className="text-xs text-gray-400 mt-0.5">{t('drawer.subtitle')}</p>
          </div>
          <button
            onClick={onClose}
            className="text-gray-400 hover:text-gray-600"
            aria-label={t('drawer.close')}
          >
            <FiX size={18} aria-hidden="true" />
          </button>
        </div>

        {/* Drawer form content */}
        <div className="flex-1 overflow-y-auto px-5 py-4 flex flex-col gap-4">

          {/* Method + Path row */}
          <div className="flex gap-2">
            <div className="flex flex-col gap-1">
              <label className="text-xs font-semibold text-gray-700">{t('drawer.methodLabel')}</label>
              <select
                value={method}
                onChange={(e) => setMethod(e.target.value as HttpMethod)}
                className="px-3 py-2 text-sm border border-gray-200 rounded-md bg-gray-50 focus:outline-none focus:ring-2 focus:ring-gray-300 transition"
                aria-label={t('drawer.methodLabel')}
              >
                {(['GET', 'POST', 'PUT', 'DELETE', 'PATCH'] as HttpMethod[]).map((m) => (
                  <option key={m}>{m}</option>
                ))}
              </select>
            </div>
            <div className="flex flex-col gap-1 flex-1">
              <label className="text-xs font-semibold text-gray-700">{t('drawer.pathLabel')}</label>
              <input
                value={path}
                onChange={(e) => setPath(e.target.value)}
                placeholder="/api/custom/my-endpoint"
                className="px-3 py-2 text-sm border border-gray-200 rounded-md bg-gray-50 focus:outline-none focus:ring-2 focus:ring-gray-300 focus:bg-white transition font-mono"
                aria-label={t('drawer.pathLabel')}
              />
            </div>
          </div>

          {/* Description field */}
          <div className="flex flex-col gap-1">
            <label className="text-xs font-semibold text-gray-700">{t('drawer.descriptionLabel')}</label>
            <input
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder={t('drawer.descriptionPlaceholder')}
              className="px-3 py-2 text-sm border border-gray-200 rounded-md bg-gray-50 focus:outline-none focus:ring-2 focus:ring-gray-300 focus:bg-white transition"
              aria-label={t('drawer.descriptionLabel')}
            />
          </div>

          {/* Authentication toggle */}
          <div className="flex flex-col gap-1">
            <label className="text-xs font-semibold text-gray-700">{t('drawer.authLabel')}</label>
            <div className="flex gap-2" role="group" aria-label={t('drawer.authLabel')}>
              <button
                onClick={() => setAuth(true)}
                className={`flex-1 flex items-center justify-center gap-1.5 py-2 text-xs font-medium rounded-md border transition ${
                  auth ? 'bg-gray-900 text-white border-gray-900' : 'bg-white text-gray-600 border-gray-200 hover:bg-gray-50'
                }`}
                aria-pressed={auth}
              >
                <FiLock size={12} aria-hidden="true" />
                {t('drawer.authRequired')}
              </button>
              <button
                onClick={() => setAuth(false)}
                className={`flex-1 flex items-center justify-center gap-1.5 py-2 text-xs font-medium rounded-md border transition ${
                  !auth ? 'bg-gray-900 text-white border-gray-900' : 'bg-white text-gray-600 border-gray-200 hover:bg-gray-50'
                }`}
                aria-pressed={!auth}
              >
                <FiUnlock size={12} aria-hidden="true" />
                {t('drawer.authPublic')}
              </button>
            </div>
          </div>

          {/* Handler code editor */}
          <div className="flex flex-col gap-1 flex-1">
            <label className="text-xs font-semibold text-gray-700">{t('drawer.codeLabel')}</label>
            <textarea
              value={code}
              onChange={(e) => setCode(e.target.value)}
              rows={16}
              className="w-full px-3 py-2 text-xs font-mono border border-gray-200 rounded-md bg-gray-900 text-green-400 focus:outline-none focus:ring-2 focus:ring-gray-500 transition resize-none"
              aria-label={t('drawer.codeLabel')}
              spellCheck={false}
            />
          </div>

        </div>

        {/* Drawer footer actions */}
        <div className="shrink-0 px-5 py-4 border-t border-gray-100 flex gap-2">
          <button
            onClick={onClose}
            className="flex-1 py-2.5 bg-white border border-gray-200 text-gray-700 text-sm font-medium rounded-md hover:bg-gray-50 transition"
          >
            {t('drawer.cancelButton')}
          </button>
          <button
            onClick={() => {
              onCreate({
                id:          Date.now().toString(),
                method,
                path,
                description,
                type:        'custom',
                auth,
              })
              onClose()
            }}
            disabled={!path.trim()}
            className="flex-1 py-2.5 bg-gray-900 text-white text-sm font-medium rounded-md hover:bg-gray-700 disabled:opacity-40 transition"
          >
            {t('drawer.createButton')}
          </button>
        </div>

      </div>
    </>
  )
}

/**
 * ApiKeysSection
 * ---------------
 * The content rendered in the "API Keys" tab.
 * Shows a list of all API keys with reveal/copy/delete actions,
 * and a form to generate a new key.
 *
 * What is an API key?
 * --------------------
 * An API key is a secret token that client applications (your Flutter or Next.js app)
 * must include in their requests to access protected API endpoints.
 * It is sent as a Bearer token in the Authorization header:
 *   Authorization: Bearer nxt_live_xxxx...
 *
 * Key masking:
 * -------------
 * By default, keys are shown in a masked format (first 12 chars + dots + last 4 chars).
 * The user can click the eye icon to reveal the full key. This is a UI-only protection —
 * the full key is already in memory. In production, full keys should only be fetched
 * from the server on explicit reveal, not returned in the initial list load.
 */
function ApiKeysSection() {
  const [keys,       setKeys]       = useState<ApiKey[]>(mockApiKeys)
  const [newName,    setNewName]    = useState('')
  const [revealed,   setRevealed]   = useState<Set<string>>(new Set())
  const [deletingId, setDeletingId] = useState<string | null>(null)

  const t = useTranslations('apiPage')

  /**
   * toggleReveal
   * -------------
   * Shows or hides the full API key value for a given key ID.
   * Uses a Set to track which keys are currently revealed.
   *
   * @param id - The API key ID to toggle
   */
  const toggleReveal = (id: string) => {
    setRevealed((prev) => {
      const next = new Set(prev)
      next.has(id) ? next.delete(id) : next.add(id)
      return next
    })
  }

  /**
   * maskKey
   * --------
   * Returns a masked version of an API key for safe display.
   * Shows the prefix (first 12 characters), then dots, then the last 4 characters.
   * Example: 'nxt_live_4f8a' + '••••••••••••••••••••' + '9b8c'
   *
   * @param key - The full API key string
   * @returns     The masked version for display
   */
  const maskKey = (key: string) => key.slice(0, 12) + '••••••••••••••••••••' + key.slice(-4)

  /**
   * createKey
   * ----------
   * Generates a new API key with the name entered by the user and adds it to the list.
   *
   * ⚠️  SECURITY WARNING — MUST FIX BEFORE PRODUCTION:
   * This currently generates the key client-side using Math.random(), which is NOT
   * cryptographically secure. API keys generated this way are predictable and unsafe.
   *
   * Before going to production:
   *  1. Move key generation to a server action or API route
   *  2. Use Node's crypto.randomBytes() on the server (as in forgotPassword.ts)
   *  3. Store only a hash of the key in the database (never the plain key)
   *  4. Return the full key to the client ONCE immediately after creation
   *     and make clear it cannot be shown again — just like GitHub personal access tokens
   *
   * Suggested API: POST /api/api-keys/create → returns { key: 'nxt_live_...' }
   */
  const createKey = () => {
    if (!newName.trim()) return

    // TODO: Replace this entire block with a server API call
    const chars = 'abcdef0123456789'
    const rand  = Array.from(
      { length: 32 },
      () => chars[Math.floor(Math.random() * chars.length)]
    ).join('')

    setKeys((prev) => [...prev, {
      id:       Date.now().toString(),
      name:     newName.trim(),
      key:      `nxt_live_${rand}`,
      created:  new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' }),
      lastUsed: t('keys.never'),
      active:   true,
    }])
    setNewName('')
  }

  return (
    <div className="flex flex-col gap-4">

      {/* ── Existing API Keys List ── */}
      <div className="bg-white border border-gray-200 rounded-lg overflow-hidden">
        <div className="px-5 py-3 border-b border-gray-100 bg-gray-50 flex items-center justify-between">
          <p className="text-xs font-bold text-gray-700">{t('keys.title')}</p>
          <p className="text-[10px] text-gray-400">{t('keys.keepSecret')}</p>
        </div>

        {keys.map((k) => (
          <div
            key={k.id}
            className="flex items-center gap-3 px-5 py-3 border-b border-gray-100 last:border-0 group"
          >
            <div className="flex-1 min-w-0">
              {/* Key name and active/inactive badge */}
              <div className="flex items-center gap-2">
                <p className="text-sm font-semibold text-gray-800">{k.name}</p>
                <span className={`text-[10px] px-1.5 py-0.5 rounded-full font-medium ${
                  k.active ? 'bg-green-50 text-green-600' : 'bg-gray-100 text-gray-400'
                }`}>
                  {k.active ? t('keys.active') : t('keys.inactive')}
                </span>
              </div>

              {/* Masked or revealed key value with reveal toggle and copy button */}
              <div className="flex items-center gap-2 mt-0.5">
                <p className="text-xs font-mono text-gray-400">
                  {revealed.has(k.id) ? k.key : maskKey(k.key)}
                </p>
                <button
                  onClick={() => toggleReveal(k.id)}
                  className="text-gray-400 hover:text-gray-600"
                  aria-label={revealed.has(k.id) ? t('keys.hideKey') : t('keys.revealKey')}
                >
                  {revealed.has(k.id)
                    ? <FiEyeOff size={11} aria-hidden="true" />
                    : <FiEye size={11} aria-hidden="true" />
                  }
                </button>
                <CopyButton text={k.key} />
              </div>

              {/* Created and last used dates */}
              <p className="text-[10px] text-gray-400 mt-0.5">
                {t('keys.created')} {k.created} · {t('keys.lastUsed')} {k.lastUsed}
              </p>
            </div>

            {/* Delete confirmation — shown on hover, requires a confirm click */}
            <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
              {deletingId === k.id ? (
                // Confirm / cancel delete buttons
                <>
                  <button
                    onClick={() => {
                      setKeys((prev) => prev.filter((key) => key.id !== k.id))
                      setDeletingId(null)
                    }}
                    className="flex items-center justify-center w-7 h-7 rounded bg-red-50 text-red-500 hover:bg-red-100 transition"
                    aria-label={t('keys.confirmDelete')}
                  >
                    <FiCheck size={13} aria-hidden="true" />
                  </button>
                  <button
                    onClick={() => setDeletingId(null)}
                    className="flex items-center justify-center w-7 h-7 rounded bg-gray-100 text-gray-500 hover:bg-gray-200 transition"
                    aria-label={t('keys.cancelDelete')}
                  >
                    <FiX size={13} aria-hidden="true" />
                  </button>
                </>
              ) : (
                // Initial delete button — clicking moves to confirm state
                <button
                  onClick={() => setDeletingId(k.id)}
                  className="flex items-center justify-center w-7 h-7 rounded bg-gray-100 text-gray-500 hover:bg-red-50 hover:text-red-500 transition"
                  aria-label={t('keys.deleteKey', { name: k.name })}
                >
                  <FiTrash2 size={13} aria-hidden="true" />
                </button>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* ── Create New Key ── */}
      <div className="bg-white border border-gray-200 rounded-lg overflow-hidden">
        <div className="px-5 py-3 border-b border-gray-100 bg-gray-50">
          <p className="text-xs font-bold text-gray-700">{t('keys.createTitle')}</p>
        </div>
        <div className="px-5 py-4 flex gap-2">
          <input
            value={newName}
            onChange={(e) => setNewName(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && createKey()}
            placeholder={t('keys.namePlaceholder')}
            className="flex-1 px-3 py-2 text-sm border border-gray-200 rounded-md bg-gray-50 focus:outline-none focus:ring-2 focus:ring-gray-300 focus:bg-white transition"
            aria-label={t('keys.nameLabel')}
          />
          <button
            onClick={createKey}
            disabled={!newName.trim()}
            className="flex items-center gap-1.5 px-4 py-2 bg-gray-900 text-white text-sm font-medium rounded-md hover:bg-gray-700 disabled:opacity-40 transition"
          >
            <FiKey size={13} aria-hidden="true" />
            {t('keys.generateButton')}
          </button>
        </div>
      </div>

    </div>
  )
}

